  pe_stage_title: ["いまのわたし", "Right now I'm…", "지금의 나", "现在的我", "現在的我", "Saat ini aku…", "ตอนนี้ฉันคือ…", "Hiện tại tôi là…", "Ngayon ako ay…", "Sekarang saya…", "Ahora mismo soy…", "No momento sou…", "En ce moment, je suis…", "Gerade bin ich…", "In questo momento sono…", "Сейчас я…", "حاليًا أنا…", "अभी मैं…", "Şu an…", "Op dit moment ben ik…"],
  pe_stage_desc: ["ひとつえらんでね。えらぶと、書く項目が変わるよ", "Pick one — the items you can fill in will change.", "하나 골라 주세요. 고르면 쓸 항목이 바뀌어요.", "选一个吧，选择后可填写的项目会改变。", "選一個吧，選擇後可填寫的項目會改變。", "Pilih satu — item yang bisa diisi akan berubah.", "เลือก 1 ข้อ แล้วหัวข้อที่ต้องเขียนจะเปลี่ยนไป", "Chọn một — các mục cần điền sẽ thay đổi.", "Pumili ng isa — magbabago ang mga item na pupunan.", "Pilih satu — item yang boleh diisi akan berubah.", "Elige uno: cambiarán los datos que puedes rellenar.", "Escolha um — os itens para preencher vão mudar.", "Choisis-en un : les éléments à remplir changeront.", "Wähle eins – die Felder passen sich an.", "Scegline uno: cambieranno le voci da compilare.", "Выберите одно — изменятся пункты анкеты.", "اختر واحدًا — ستتغيّر العناصر التي تملؤها.", "एक चुनें — भरने वाले आइटम बदल जाएँगे।", "Birini seç; doldurulacak alanlar değişir.", "Kies er één – de invulvelden veranderen mee."],
  stamp_chosen: ["えらんだ", "Picked", "선택", "已选", "已選", "Dipilih", "เลือกแล้ว", "Đã chọn", "Pinili", "Dipilih", "Elegido", "Escolhido", "Choisi", "Gewählt", "Scelto", "Выбрано", "مختار", "चुना", "Seçildi", "Gekozen"],
  pe_activity_title: ["特技・活動", "Skills & hobbies", "특기·활동", "特长·活动", "特長·活動", "Keahlian & hobi", "ความสามารถ & กิจกรรม", "Sở trường & hoạt động", "Galing at libangan", "Kemahiran & hobi", "Talentos y hobbies", "Talentos e hobbies", "Talents et loisirs", "Talente & Hobbys", "Talenti e hobby", "Таланты и хобби", "المهارات والهوايات", "हुनर और शौक", "Yetenek ve hobiler", "Talenten & hobby's"],
  pe_if_any: ["あれば", "Optional", "선택", "可选", "可選", "Opsional", "ไม่บังคับ", "Tùy chọn", "Opsyonal", "Pilihan", "Opcional", "Opcional", "Facultatif", "Optional", "Facoltativo", "Необязательно", "اختياري", "वैकल्पिक", "İsteğe bağlı", "Optioneel"],
  pe_activity_desc: ["あなたらしいシールを1枚はってね。はると専用の項目がふえるよ", "Put on a sticker that's so you — it adds extra items to fill in.", "나다운 스티커를 한 장 붙여 보세요. 붙이면 전용 항목이 늘어나요.", "贴一张最像你的贴纸吧，贴上后会多出专属项目。", "貼一張最像你的貼紙吧，貼上後會多出專屬項目。", "Tempel satu stiker yang paling kamu — akan ada item tambahan.", "แปะสติกเกอร์ที่เป็นตัวคุณ 1 แผ่น แล้วจะมีหัวข้อเพิ่ม", "Dán một nhãn dán đúng chất bạn — sẽ có thêm mục riêng.", "Magdikit ng sticker na bagay sa iyo — madadagdagan ang mga item.", "Tampal satu pelekat yang paling anda — item tambahan akan muncul.", "Pega una pegatina que te represente: añadirá datos extra.", "Cole um adesivo que seja a sua cara — aparecem itens extras.", "Colle un sticker qui te ressemble : de nouveaux éléments apparaîtront.", "Kleb einen Sticker, der zu dir passt – dann gibt es extra Felder.", "Attacca un adesivo che ti rappresenta: si aggiungono voci extra.", "Наклейте стикер, который похож на вас, — появятся новые пункты.", "ألصق ملصقًا يشبهك — ستظهر عناصر إضافية.", "अपने जैसा एक स्टिकर लगाएँ — और आइटम जुड़ जाएँगे।", "Sana uyan bir çıkartma yapıştır; ek alanlar açılır.", "Plak een sticker die bij je past – er komen extra velden bij."],
  grp_sports: ["スポーツ", "Sports", "스포츠", "运动", "運動", "Olahraga", "กีฬา", "Thể thao", "Sports", "Sukan", "Deportes", "Esportes", "Sport", "Sport", "Sport", "Спорт", "رياضة", "खेल", "Spor", "Sport"],
